const dailyTheme = isSabbath ? 'Sabbath' : themes[dayOfYear % themes.length];
const intro_music_url = null;
return [{ json: { today_date: now.toLocaleDateString('en-US', {weekday: 'long', year: 'numeric', month: 'long', day: 'numeric'}), day_of_week: dayOfWeek, is_sabbath: isSabbath, daily_theme: dailyTheme, date_iso: now.toISOString().split('T')[0], intro_music_url } }];

const aiOutput = $input.first().json.output || $input.first().json.text || '';
let verseData;
try { verseData = JSON.parse(aiOutput.trim()); } catch (e) {
  const jsonMatch = aiOutput.match(/\{[\s\S]*\}/);
  if (!jsonMatch) throw new Error('Could not parse AI JSON: ' + aiOutput.slice(0, 300));
  verseData = JSON.parse(jsonMatch[0]);
}

// Strip smart quotes, dashes, non-ASCII — English alphabet only
function sanitize(text) {
  if (!text) return '';
  return text
    .replace(/['']/g, "'")
    .replace(/[""]/g, '"')
    .replace(/[–—]/g, '-')
    .replace(/…/g, '...')
    .replace(/[^\x20-\x7E\n]/g, '')
    .replace(/\s+/g, ' ')
    .trim();
}

// Normalize to "BookName Chapter:Verse (KJV)" — e.g. "1 Thessalonians 4:16 (KJV)"
function normalizeRef(ref) {
  if (!ref) return '';
  let r = ref.replace(/[^\x20-\x7E]/g, '').trim();
  r = r.replace(/(\d)\s+(\d)/g, '$1:$2');
  r = r.replace(/\s*\(?KJV\)?\s*$/i, '').trim();
  return r + ' (KJV)';
}

verseData.verse_text = sanitize(verseData.verse_text || '');
verseData.verse_ref = normalizeRef(verseData.verse_ref || '');
verseData.tts_script = sanitize(verseData.tts_script || '');

